'use client';

import React, { useEffect, useState } from 'react';
import {
  Bar,
  BarChart,
  CartesianGrid,
  Legend,
  Line,
  LineChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts';
import { AlertTriangle, Package, TrendingUp, Users } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';
import { apiRequest, useAuth } from '../contexts/AuthContext';
import { useCurrency } from '../contexts/CurrencyContext';
import { Sidebar } from '../components/Sidebar';

interface DashboardStats {
  monthlyRevenue: number;
  totalProducts: number;
  lowStockCount: number;
}

interface ChartData {
  date: string;
  revenue: number;
  transactions?: number;
  profit?: number;
}

interface LowStockProduct {
  id: number;
  name_en: string;
  name_ar: string;
  stock_quantity: number;
  min_stock_level: number;
  category_name_en?: string;
  category_name_ar?: string;
}

export default function DashboardPage() {
  const { t, language } = useLanguage();
  const { user } = useAuth();
  const { format } = useCurrency();
  const [stats, setStats] = useState<DashboardStats>({
    monthlyRevenue: 0,
    totalProducts: 0,
    lowStockCount: 0,
  });
  const [salesChartData, setSalesChartData] = useState<ChartData[]>([]);
  const [profitChartData, setProfitChartData] = useState<ChartData[]>([]);
  const [lowStockProducts, setLowStockProducts] = useState<LowStockProduct[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadDashboardData();
  }, []);

  const loadDashboardData = async () => {
    try {
      setLoading(true);
      const [statsData, salesData, profitData, lowStockData] = await Promise.all([
        apiRequest('/dashboard/stats'),
        apiRequest('/dashboard/sales-chart?days=30'),
        apiRequest('/dashboard/profit-chart?days=30'),
        apiRequest('/products/low-stock'),
      ]);

      setStats(statsData);
      setSalesChartData(salesData);
      setProfitChartData(profitData);
      setLowStockProducts(lowStockData);
    } catch (error) {
      console.error('Failed to load dashboard data:', error);
    } finally {
      setLoading(false);
    }
  };

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    return new Intl.DateTimeFormat('ar-SA', {
      month: 'short',
      day: 'numeric',
    }).format(date);
  };

  return (
    <div className="min-h-screen bg-black text-white flex" dir="rtl">
      <Sidebar />

      {/* Main Content */}
      <div className="flex-1 p-8 overflow-y-auto">
        <div className="flex items-center justify-between mb-6">
          <h1 className="text-2xl font-bold text-cyan-200">لوحة التحكم</h1>
          <div className="text-xs text-gray-500">
            الباقة:{' '}
            <span className="inline-flex items-center px-2 py-1 rounded-full text-[10px] uppercase text-yellow-300 border border-yellow-500/50 bg-yellow-500/10 shadow-[0_0_12px_rgba(255,215,0,0.35)]">
              {user?.package || 'bronze'}
            </span>
          </div>
        </div>
        {/* Header Stats */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
          <div className="p-6 neon-card rounded-xl neon-glow-cyan">
            <div className="flex items-center justify-between mb-2">
              <p className="text-gray-400 text-sm">إجمالي المبيعات</p>
              <TrendingUp className="w-5 h-5 text-cyan-400" />
            </div>
            <h3 className="text-3xl font-bold text-cyan-400">
              {loading ? '...' : format(stats.monthlyRevenue)}
            </h3>
          </div>
          <div className="p-6 neon-card rounded-xl neon-glow-fuchsia">
            <div className="flex items-center justify-between mb-2">
              <p className="text-gray-400 text-sm">إجمالي المنتجات</p>
              <Package className="w-5 h-5 text-fuchsia-400" />
            </div>
            <h3 className="text-3xl font-bold text-fuchsia-400">
              {loading ? '...' : stats.totalProducts.toLocaleString()}
            </h3>
          </div>
          <div className="p-6 neon-card rounded-xl">
            <div className="flex items-center justify-between mb-2">
              <p className="text-gray-400 text-sm">الموظفون المتصلون</p>
              <Users className="w-5 h-5 text-cyan-400" />
            </div>
            <h3 className="text-3xl font-bold text-yellow-500">8</h3>
          </div>
        </div>

        {/* Charts Row */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-8">
          {/* Sales Chart */}
          <div className="p-6 neon-card rounded-xl">
            <h3 className="text-xl font-bold mb-4 text-cyan-200">تحليلات المبيعات</h3>
            {loading ? (
              <div className="h-64 flex items-center justify-center">
                <p className="text-gray-500">{t('common.loading')}</p>
              </div>
            ) : (
              <ResponsiveContainer width="100%" height={300}>
                <LineChart data={salesChartData}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#1f2937" />
                  <XAxis dataKey="date" stroke="#94a3b8" tickFormatter={formatDate} />
                  <YAxis stroke="#94a3b8" />
                  <Tooltip
                    contentStyle={{ backgroundColor: '#0b1220', border: '1px solid #00f3ff', borderRadius: '8px' }}
                    labelStyle={{ color: '#00f3ff' }}
                  />
                  <Legend />
                  <Line
                    type="monotone"
                    dataKey="revenue"
                    stroke="#00f3ff"
                    strokeWidth={2}
                    dot={{ fill: '#00f3ff', r: 4 }}
                    name="المبيعات"
                  />
                  <Line
                    type="monotone"
                    dataKey="transactions"
                    stroke="#ec4899"
                    strokeWidth={2}
                    dot={{ fill: '#ec4899', r: 4 }}
                    name="العمليات"
                  />
                </LineChart>
              </ResponsiveContainer>
            )}
          </div>

          {/* Profit Chart */}
          <div className="p-6 neon-card rounded-xl">
            <h3 className="text-xl font-bold mb-4 text-cyan-200">الأرباح</h3>
            {loading ? (
              <div className="h-64 flex items-center justify-center">
                <p className="text-gray-500">{t('common.loading')}</p>
              </div>
            ) : (
              <ResponsiveContainer width="100%" height={300}>
                <BarChart data={profitChartData}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#1f2937" />
                  <XAxis dataKey="date" stroke="#94a3b8" tickFormatter={formatDate} />
                  <YAxis stroke="#94a3b8" />
                  <Tooltip
                    contentStyle={{ backgroundColor: '#0b1220', border: '1px solid #00f3ff', borderRadius: '8px' }}
                    labelStyle={{ color: '#00f3ff' }}
                  />
                  <Legend />
                  <Bar dataKey="revenue" fill="#00f3ff" name="المبيعات" />
                  <Bar dataKey="profit" fill="#ec4899" name="الأرباح" />
                </BarChart>
              </ResponsiveContainer>
            )}
          </div>
        </div>

        {/* Low Stock Alerts & Recent Stock */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {/* Low Stock Alerts */}
          <div className="p-6 neon-card rounded-xl border border-fuchsia-500/40 shadow-[0_0_18px_rgba(236,72,153,0.35)]">
            <div className="flex items-center gap-2 mb-4">
              <AlertTriangle className="w-5 h-5 text-red-400" />
              <h3 className="text-xl font-bold text-cyan-200">تنبيهات المخزون المنخفض</h3>
              <span className="ml-auto bg-red-500/20 text-red-400 px-3 py-1 rounded-full text-sm font-bold">
                {lowStockProducts.length}
              </span>
            </div>
            <div className="space-y-3 max-h-64 overflow-y-auto">
              {loading ? (
                <p className="text-gray-500 text-center py-4">{t('common.loading')}</p>
              ) : lowStockProducts.length === 0 ? (
                <p className="text-gray-500 text-center py-4">
                  {language === 'ar' ? 'لا توجد تنبيهات' : 'No alerts'}
                </p>
              ) : (
                lowStockProducts.map((product) => (
                  <div key={product.id} className="bg-gray-800 p-3 rounded-lg border-l-4 border-red-500">
                    <div className="flex justify-between items-start">
                      <div>
                        <h4 className="font-medium text-white">
                          {language === 'ar' ? product.name_ar : product.name_en}
                        </h4>
                        {product.category_name_ar && (
                          <p className="text-xs text-gray-400 mt-1">
                            {language === 'ar' ? product.category_name_ar : product.category_name_en}
                          </p>
                        )}
                      </div>
                      <div className="text-right">
                        <p className="text-red-400 font-bold">
                          {product.stock_quantity} / {product.min_stock_level}
                        </p>
                        <p className="text-xs text-gray-500">
                          {language === 'ar' ? 'المتبقي' : 'remaining'}
                        </p>
                      </div>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>

          {/* Recent Stock Update */}
          <div className="p-6 neon-card rounded-xl">
            <h3 className="text-xl font-bold mb-4 text-cyan-200">تحديثات المخزون الأخيرة</h3>
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead>
                  <tr className="border-b border-gray-800 text-cyan-500">
                    <th className="pb-3 px-2">{language === 'ar' ? 'اسم المنتج' : 'Product Name'}</th>
                    <th className="pb-3 px-2">{language === 'ar' ? 'المخزون' : 'Stock'}</th>
                    <th className="pb-3 px-2">{language === 'ar' ? 'السعر' : 'Price'}</th>
                  </tr>
                </thead>
                <tbody className="text-gray-300">
                  {loading ? (
                    <tr>
                      <td colSpan={3} className="py-4 text-center text-gray-500">
                        {t('common.loading')}
                      </td>
                    </tr>
                  ) : (
                    <tr className="border-b border-gray-900 hover:bg-gray-800 transition">
                      <td className="py-3 px-2">{language === 'ar' ? 'مثال: فلتر زيت' : 'Example: Oil Filter'}</td>
                      <td className="py-3 px-2 text-green-400">45</td>
                      <td className="py-3 px-2">2.00</td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

